import{_ as e,c as o,o as s,ai as i}from"./chunks/framework.DMRKKuRm.js";const h=JSON.parse('{"title":"Survival Vanilla","description":"","frontmatter":{},"headers":[],"relativePath":"Reglas/survival-vanilla.md","filePath":"Reglas/survival-vanilla.md"}'),r={name:"Reglas/survival-vanilla.md"};function l(n,a,t,c,d,u){return s(),o("div",null,a[0]||(a[0]=[i('<h1 id="survival-vanilla" tabindex="-1">Survival Vanilla <a class="header-anchor" href="#survival-vanilla" aria-label="Permalink to &quot;Survival Vanilla&quot;">​</a></h1><p>Reglas específicas para el modo Survival Vanilla en SilkCraft Network.</p><h2 id="concepto-de-survival-vanilla" tabindex="-1">Concepto de Survival Vanilla <a class="header-anchor" href="#concepto-de-survival-vanilla" aria-label="Permalink to &quot;Concepto de Survival Vanilla&quot;">​</a></h2><p>El Survival Vanilla es un modo de juego que busca mantener la experiencia clásica de Minecraft Survival, con algunas mejoras de calidad de vida proporcionadas por plugins del servidor.</p><h2 id="reglas-especificas" tabindex="-1">Reglas Específicas <a class="header-anchor" href="#reglas-especificas" aria-label="Permalink to &quot;Reglas Específicas&quot;">​</a></h2><h3 id="construccion" tabindex="-1">Construcción <a class="header-anchor" href="#construccion" aria-label="Permalink to &quot;Construcción&quot;">​</a></h3><h4 id="claims" tabindex="-1">Claims <a class="header-anchor" href="#claims" aria-label="Permalink to &quot;Claims&quot;">​</a></h4><ul><li><strong>Protege tus construcciones:</strong> Usa <code>/claim</code> para proteger tus builds</li><li><strong>Límites de claims:</strong> Los límites de claims dependen de tu rango <ul><li>Default: 1 claim básico</li><li>VIP: +3 claims adicionales</li><li>VIP+: +5 claims adicionales</li><li>MVP: +10 claims adicionales</li><li>MVP+: +15 claims adicionales</li></ul></li></ul><h4 id="construcciones-permitidas" tabindex="-1">Construcciones Permitidas <a class="header-anchor" href="#construcciones-permitidas" aria-label="Permalink to &quot;Construcciones Permitidas&quot;">​</a></h4><ul><li>Construcciones normales de Minecraft</li><li>Farms automáticos (con límites razonables)</li><li>Redstone complejo (si no causa lag)</li></ul><h4 id="construcciones-prohibidas" tabindex="-1">Construcciones Prohibidas <a class="header-anchor" href="#construcciones-prohibidas" aria-label="Permalink to &quot;Construcciones Prohibidas&quot;">​</a></h4><ul><li><strong>Lag machines:</strong> Cualquier construcción que cause lag intencional</li><li><strong>Construcciones ofensivas:</strong> Construcciones con contenido inapropiado</li><li><strong>Exploits:</strong> Uso de bugs para obtener ventajas</li></ul><h3 id="pvp" tabindex="-1">PvP <a class="header-anchor" href="#pvp" aria-label="Permalink to &quot;PvP&quot;">​</a></h3><h4 id="reglas-de-pvp" tabindex="-1">Reglas de PvP <a class="header-anchor" href="#reglas-de-pvp" aria-label="Permalink to &quot;Reglas de PvP&quot;">​</a></h4><ul><li>El PvP está <strong>desactivado por defecto</strong> en Survival</li><li>Puedes activar PvP en áreas designadas o con consentimiento mutuo</li><li>No mates a jugadores que no quieren PvP</li><li>No uses exploits o bugs para ganar ventajas en PvP</li></ul><h4 id="arenas-de-pvp" tabindex="-1">Arenas de PvP <a class="header-anchor" href="#arenas-de-pvp" aria-label="Permalink to &quot;Arenas de PvP&quot;">​</a></h4><ul><li>Hay arenas designadas para PvP</li><li>Las reglas de las arenas pueden variar</li><li>Consulta las reglas específicas de cada arena antes de participar</li></ul><h3 id="economia" tabindex="-1">Economía <a class="header-anchor" href="#economia" aria-label="Permalink to &quot;Economía&quot;">​</a></h3><h4 id="sistema-de-economia" tabindex="-1">Sistema de Economía <a class="header-anchor" href="#sistema-de-economia" aria-label="Permalink to &quot;Sistema de Economía&quot;">​</a></h4><ul><li>El servidor tiene un sistema de economía basado en dinero virtual</li><li>Puedes ganar dinero vendiendo items, completando misiones, o vendiendo a otros jugadores</li><li>Puedes usar dinero para comprar items en el shop del servidor</li></ul><h4 id="comercio" tabindex="-1">Comercio <a class="header-anchor" href="#comercio" aria-label="Permalink to &quot;Comercio&quot;">​</a></h4><ul><li>El comercio entre jugadores está permitido</li><li>Usa <code>/pay &lt;jugador&gt; &lt;cantidad&gt;</code> para pagar a otros jugadores</li><li>Sé honesto en tus transacciones</li><li>Reporta estafas al staff</li></ul><h3 id="recursos" tabindex="-1">Recursos <a class="header-anchor" href="#recursos" aria-label="Permalink to &quot;Recursos&quot;">​</a></h3><h4 id="generacion-de-recursos" tabindex="-1">Generación de Recursos <a class="header-anchor" href="#generacion-de-recursos" aria-label="Permalink to &quot;Generación de Recursos&quot;">​</a></h4><ul><li>Los recursos se generan de forma vanilla</li><li>No hay generación custom de recursos</li><li>Respeta los límites de claims al minar</li></ul><h4 id="farms" tabindex="-1">Farms <a class="header-anchor" href="#farms" aria-label="Permalink to &quot;Farms&quot;">​</a></h4><ul><li>Las farms están permitidas</li><li>No crees farms que causen lag excesivo</li><li>Respeta los límites de entidades</li><li>El staff puede pedirte que reduzcas el tamaño de tu farm si causa problemas</li></ul><h3 id="mobs-y-spawners" tabindex="-1">Mobs y Spawners <a class="header-anchor" href="#mobs-y-spawners" aria-label="Permalink to &quot;Mobs y Spawners&quot;">​</a></h3><h4 id="spawners" tabindex="-1">Spawners <a class="header-anchor" href="#spawners" aria-label="Permalink to &quot;Spawners&quot;">​</a></h4><ul><li>Los spawners funcionan de forma vanilla</li><li>Puedes usar spawners para crear farms</li><li>No abuses de spawners para causar lag</li></ul><h4 id="mobs" tabindex="-1">Mobs <a class="header-anchor" href="#mobs" aria-label="Permalink to &quot;Mobs&quot;">​</a></h4><ul><li>Los mobs se comportan de forma vanilla</li><li>No uses exploits para manipular el comportamiento de los mobs</li><li>Respeta los límites de entidades</li></ul><h2 id="comandos-disponibles" tabindex="-1">Comandos Disponibles <a class="header-anchor" href="#comandos-disponibles" aria-label="Permalink to &quot;Comandos Disponibles&quot;">​</a></h2><h3 id="comandos-basicos" tabindex="-1">Comandos Básicos <a class="header-anchor" href="#comandos-basicos" aria-label="Permalink to &quot;Comandos Básicos&quot;">​</a></h3><ul><li><code>/spawn</code> - Teletransporta al spawn</li><li><code>/home</code> - Teletransporta a tu casa</li><li><code>/sethome &lt;nombre&gt;</code> - Establece un punto de casa</li><li><code>/delhome &lt;nombre&gt;</code> - Elimina un punto de casa</li><li><code>/homes</code> - Lista todas tus casas</li></ul><h3 id="comandos-de-proteccion" tabindex="-1">Comandos de Protección <a class="header-anchor" href="#comandos-de-proteccion" aria-label="Permalink to &quot;Comandos de Protección&quot;">​</a></h3><ul><li><code>/claim</code> - Protege el área donde estás</li><li><code>/unclaim</code> - Desprotege un área</li><li><code>/trust &lt;jugador&gt;</code> - Da permisos a un jugador en tu claim</li><li><code>/untrust &lt;jugador&gt;</code> - Quita permisos a un jugador de tu claim</li></ul><h3 id="comandos-de-economia" tabindex="-1">Comandos de Economía <a class="header-anchor" href="#comandos-de-economia" aria-label="Permalink to &quot;Comandos de Economía&quot;">​</a></h3><ul><li><code>/balance</code> o <code>/bal</code> - Muestra tu balance</li><li><code>/pay &lt;jugador&gt; &lt;cantidad&gt;</code> - Paga a otro jugador</li><li><code>/baltop</code> - Muestra el top de jugadores más ricos</li></ul><p>Para una lista completa de comandos, consulta <a href="/Servidor/comandos-generales.html">Comandos Generales</a>.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas Frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas Frecuentes&quot;">​</a></h2><h3 id="¿puedo-usar-mods-en-survival" tabindex="-1">¿Puedo usar mods en Survival? <a class="header-anchor" href="#¿puedo-usar-mods-en-survival" aria-label="Permalink to &quot;¿Puedo usar mods en Survival?&quot;">​</a></h3><p>Consulta <a href="/Reglas/clientes.html">Reglas de Clientes</a> para información sobre mods permitidos.</p><h3 id="¿hay-limites-de-construccion" tabindex="-1">¿Hay límites de construcción? <a class="header-anchor" href="#¿hay-limites-de-construccion" aria-label="Permalink to &quot;¿Hay límites de construcción?&quot;">​</a></h3><p>No hay límites estrictos, pero el staff puede pedirte que reduzcas el tamaño de construcciones que causen lag.</p><h3 id="¿puedo-hacer-farms-automaticos" tabindex="-1">¿Puedo hacer farms automáticos? <a class="header-anchor" href="#¿puedo-hacer-farms-automaticos" aria-label="Permalink to &quot;¿Puedo hacer farms automáticos?&quot;">​</a></h3><p>Sí, las farms automáticas están permitidas siempre que no causen lag excesivo.</p><h3 id="¿que-pasa-si-alguien-destruye-mi-construccion" tabindex="-1">¿Qué pasa si alguien destruye mi construcción? <a class="header-anchor" href="#¿que-pasa-si-alguien-destruye-mi-construccion" aria-label="Permalink to &quot;¿Qué pasa si alguien destruye mi construcción?&quot;">​</a></h3><p>Reporta el griefing al staff con evidencia. El staff puede restaurar construcciones si es posible.</p><h3 id="¿puedo-tener-multiples-casas" tabindex="-1">¿Puedo tener múltiples casas? <a class="header-anchor" href="#¿puedo-tener-multiples-casas" aria-label="Permalink to &quot;¿Puedo tener múltiples casas?&quot;">​</a></h3><p>Sí, el número de casas depende de tu rango. Consulta <a href="/Servidor/rangos.html">Rangos</a> para más información.</p><h3 id="¿hay-un-limite-de-tiempo-de-juego" tabindex="-1">¿Hay un límite de tiempo de juego? <a class="header-anchor" href="#¿hay-un-limite-de-tiempo-de-juego" aria-label="Permalink to &quot;¿Hay un límite de tiempo de juego?&quot;">​</a></h3><p>No, puedes jugar tanto como quieras.</p><hr><p><strong>Recuerda:</strong> El Survival Vanilla busca mantener la experiencia clásica de Minecraft. Disfruta construyendo, explorando y sobreviviendo!</p><p>Para más información sobre reglas generales, consulta <a href="/Reglas/normativa-general.html">Normativa General</a>.</p>',56)]))}const p=e(r,[["render",l]]);export{h as __pageData,p as default};
